    '\n'
    '    expect_failure(\n'
    '        "malformed indicator sheet date column",\n'
    '        lambda: get_sheet_layout([["Notes", "Value"], ["bad", "1"]]),\n'
    '    )\n'
    '    if indicator_sheet_name("Manufacturing PMI", {"manufacturing pmi"}) is not None:\n'
