    '\n'
    '\n'
    'def calculate_core_inflation_outputs(raw_df: Any) -> Any:\n'
    '    records = df_records(raw_df)\n'
    '    b = [\n'
    '        to_float_or_none(r.get("Raw Value", r.get("B", r.get("Value", ""))))\n'
    '        for r in records\n'
    '    ]\n'
    '    c_vals = []\n'
    '    numeric_b_count = 0\n'
