    '                "12M Core Inflation Score": k,\n'
    '                "3M Annualised Core Inflation PercentRank": (\n'
    '                    l_rank if l_rank is not None else ""\n'
    '                ),\n'
    '                "3M Annualised Core Inflation Score": m,\n'
