    '\n'
    '\n'
    'def _interest_coverage_vulnerability_score(\n'
    '    e: Any, aj: Any, ak: Any, al: Any, am: Any\n'
    ') -> Any:\n'
    '    if any(is_blank(x) for x in (e, aj, ak, al, am)):\n'
