    '        return 4\n'
    '    return 0\n'
    '\n'
    '\n'
    'def _interest_coverage_recovery_score(g: Any, h: Any) -> Any:\n'
    '    if any(is_blank(x) for x in (g, h)):\n'
    '        return ""\n'
    '    if g > 0 and h > 0:\n'
    '        return 5\n'
    '    if g < 0 and h < 0:\n'
    '        return -5\n'
    '    if g > 0 and h < 0:\n'
    '        return 3\n'
    '    if g < 0 and h > 0:\n'
    '        return -3\n'
    '    return 0\n'
    '\n'
    '\n'
    'def _interest_coverage_shock_score(g: Any) -> Any:\n'
    '    if is_blank(g):\n'
    '        return ""\n'
    '    if g >= 2:\n'
